                        if 0<=x<h and 0<=y<w and g[x][y]==5 and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                comps.append(comp)
    for comp in comps:
        rs=[a for a,b in comp]; cs=[b for a,b in comp]
        top,bot,l,r=min(rs),max(rs),min(cs),max(cs)
        # outside flood: cells not enclosed (treat 5 as wall)
        out=[[False]*w for _ in range(h)]; q=deque()
        for i in range(h):
            for j in (0,w-1):
                if g[i][j]!=5 and not out[i][j]: out[i][j]=True;q.append((i,j))
        for j in range(w):
            for i in (0,h-1):
                if g[i][j]!=5 and not out[i][j]: out[i][j]=True;q.append((i,j))
        while q:
            a,b=q.popleft()
            for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                x,y=a+da,b+db
                if 0<=x<h and 0<=y<w and g[x][y]!=5 and not out[x][y]:
                    out[x][y]=True;q.append((x,y))
